import com.mirrorlink.mobile.PairLink;import com.google.zxing.*;import com.google.zxing.common.HybridBinarizer;import java.nio.file.*;import java.util.*;
public class PairQrTest {public static void main(String[] args)throws Exception{List<String> lines=Files.readAllLines(Path.of(args[0]));String expected=lines.get(0);int size=lines.size()-1,scale=4,border=4,w=(size+border*2)*scale;int[] pixels=new int[w*w];Arrays.fill(pixels,0xffffff);for(int y=0;y<size;y++)for(int x=0;x<size;x++)if(lines.get(y+1).charAt(x)=='1')for(int dy=0;dy<scale;dy++)for(int dx=0;dx<scale;dx++)pixels[((y+border)*scale+dy)*w+(x+border)*scale+dx]=0;String decoded=new MultiFormatReader().decode(new BinaryBitmap(new HybridBinarizer(new RGBLuminanceSource(w,w,pixels)))).getText();if(!decoded.equals(expected))throw new AssertionError("QR roundtrip");PairLink pair=PairLink.parse(decoded);if(!pair.address.equals("192.168.1.8:52345")||!pair.code.equals("001234"))throw new AssertionError("Pair fields");for(String bad:new String[]{"https://example.com","yinlian://pair?address=8.8.8.8&code=001234","yinlian://pair?address=192.168.1.8&code=123","yinlian://pair?address=192.168.1.8&code=001234&code=001234"})try{PairLink.parse(bad);throw new AssertionError("unsafe link");}catch(IllegalArgumentException ok){}System.out.println("PASS QR generation / ZXing decoding / LAN-only pair links");}}
